import unittest
from candidate import flip_case

class TestFlipCase(unittest.TestCase):
    def test_normal_mixed_case(self):
        self.assertEqual(flip_case('Hello'), 'hELLO')

    def test_all_lowercase(self):
        self.assertEqual(flip_case('abc'), 'ABC')

    def test_all_uppercase(self):
        self.assertEqual(flip_case('XYZ'), 'xyz')

    def test_with_numbers_and_symbols(self):
        self.assertEqual(flip_case('Test123!@#'), 'tEST123!@#')

    def test_empty_string(self):
        self.assertEqual(flip_case(''), '')

    def test_single_lowercase_char(self):
        self.assertEqual(flip_case('a'), 'A')

    def test_single_uppercase_char(self):
        self.assertEqual(flip_case('A'), 'a')

    def test_with_spaces(self):
        self.assertEqual(flip_case('Ab Cd Ef'), 'aB cD eF')

    def test_whitespace_only(self):
        self.assertEqual(flip_case('   '), '   ')

    def test_with_newlines(self):
        self.assertEqual(flip_case('Hello\nWorld'), 'hELLO\nwORLD')

    def test_unicode_characters(self):
        self.assertEqual(flip_case('café'), 'CAFÉ')

    def test_none_input_raises_error(self):
        with self.assertRaises(Exception):
            flip_case(None)

    def test_integer_input_raises_error(self):
        with self.assertRaises(Exception):
            flip_case(123)

    def test_list_input_raises_error(self):
        with self.assertRaises(Exception):
            flip_case([1, 2, 3])

if __name__ == '__main__':
    unittest.main()
